pitfalls.bad:
-- runtime: sql
BEGIN;
INSERT INTO t VALUES (1);
ROLLBACK; -- refused: the run stops here

pitfalls.good:
-- runtime: sql
SAVEPOINT s;
INSERT INTO t VALUES (1);
ROLLBACK TO SAVEPOINT s;

files.examples/01_inside_the_sandbox.sql:
-- Runtime sql. Before your first line runs, sqlrun.Run has sent, as one message:
--   BEGIN; CREATE SCHEMA run_<nanos>_<hex>;
--   SET LOCAL search_path TO run_...; SET LOCAL statement_timeout = 5000;
--   SET LOCAL lock_timeout = 2000;
-- and after your last line it sends ROLLBACK.

-- The schema name changes on every run, so mask it.
SELECT regexp_replace(current_schema(), '^run_\d+_[0-9a-f]{8}$', 'run_<nanos>_<hex>') AS schema,
       current_setting('statement_timeout') AS statement_timeout,
       current_setting('lock_timeout') AS lock_timeout;

-- You are already inside a transaction, and it has written: CREATE SCHEMA.
SELECT pg_current_xact_id_if_assigned() IS NOT NULL AS has_xid,
       transaction_timestamp() < statement_timestamp() AS began_before_this_statement;

-- Unqualified names land in the run's schema, never in public.
CREATE TABLE notes (id int PRIMARY KEY, body text);
INSERT INTO notes VALUES (1, 'gone after ROLLBACK');
SELECT c.relnamespace::regnamespace::text = current_schema() AS in_run_schema,
       to_regclass('public.notes') AS public_notes
FROM pg_class c
WHERE c.oid = 'notes'::regclass;

-- A BEGIN of your own changes nothing: there is only one transaction.
BEGIN;

files.examples/02_invisible_to_others.sql:
-- A does what sqlrun.Run does to every lesson: DDL and data in one open transaction.
A: BEGIN;
A: CREATE TABLE scratch (id int);
A: INSERT INTO scratch VALUES (1), (2);

-- B shares the schema (same search_path), but catalog rows are MVCC rows too.
B: SELECT to_regclass('scratch') AS scratch;

-- B claims the same name: the catalog's unique index waits for A's outcome.
B: CREATE TABLE scratch (id int);
A: ROLLBACK;

-- A's table and rows never existed for anyone; the table now is B's, empty.
A: SELECT count(*) AS rows_from_a FROM scratch;

files.examples/03_your_rollback_is_refused.sql:
-- Runtime sql: the sandbox is one transaction, so ending it yourself would end
-- the sandbox. sqlrun refuses COMMIT, ROLLBACK, END and ABORT here.
CREATE TABLE drafts (id int);

-- Savepoints rewind inside the one transaction, so they stay allowed.
SAVEPOINT before_drop;
DROP TABLE drafts;
ROLLBACK TO SAVEPOINT before_drop;
SELECT to_regclass('drafts') IS NOT NULL AS drafts_is_back;

-- Refused before it reaches the server; the run stops here.
ROLLBACK;
SELECT 'never runs';
